public static void solve(Scanner in) {
    long islands = in.nextLong();
    long connections = in.nextLong();
    long[] bridgeCrossings = new long[(int) islands + 1];
    long lastIsland = -1;
    long totalTourLength = 0;

    for (long i = 0; i < connections; i++) {
        long currentIsland = in.nextLong();
        if (lastIsland != -1) {
            long minIsland = Math.min(lastIsland, currentIsland);
            long maxIsland = Math.max(lastIsland, currentIsland);
            long directCost = maxIsland - minIsland;
            long wrapAroundCost = minIsland + islands - maxIsland;
            totalTourLength += Math.min(directCost, wrapAroundCost);

            if (directCost > wrapAroundCost) {
                bridgeCrossings[0] += wrapAroundCost;
                bridgeCrossings[(int) minIsland] -= wrapAroundCost;
                bridgeCrossings[(int) maxIsland] += wrapAroundCost;
            } else {
                bridgeCrossings[(int) minIsland] += directCost;
                bridgeCrossings[(int) maxIsland] -= directCost;
            }
        }
        lastIsland = currentIsland;
    }

    long minTourLength = Long.MAX_VALUE;
    long currentCrossingSum = 0;
    for (int i = 0; i < islands; i++) {
        currentCrossingSum += bridgeCrossings[i];
        minTourLength = Math.min(minTourLength, currentCrossingSum);
    }

    System.out.println(totalTourLength + minTourLength);
}
